// Export only nontrivial exteriors of disjoint red-edge footprints on order 27.
use std::io::{self,BufRead};fn main(){let ids=std::env::args().nth(1).as_deref()==Some("ids");for(row,l)in io::stdin().lock().lines().enumerate(){let s=l.unwrap();let b=s.as_bytes();let n=(b[0]-63)as usize;let mut a=vec![0u32;n];let mut e=vec![];let mut h=0;for j in 0..n{for i in 0..j{if (b[1+h/6]-63)>>(5-h%6)&1!=0{a[i]|=1<<j;a[j]|=1<<i;e.push((i,j))}h+=1}}let bs:Vec<_>=e.iter().map(|&(i,j)|a[i]|a[j]).collect();for(i,&v)in bs.iter().enumerate(){for(j,&w)in bs[..i].iter().enumerate(){if v&w!=0{continue}let u=((1<<n)-1)&!(v|w);if u.count_ones()<5{continue}let vs:Vec<_>=(0..n).filter(|j|u>>j&1!=0).collect();if ids{print!("{} {} {} {} {} {} ",row,s,e[i].0,e[i].1,e[j].0,e[j].1)}println!("{}",vs.iter().map(|&j|vs.iter().enumerate().map(|(i,&h)|((a[j]>>h)&1)<<i).sum::<u32>().to_string()).collect::<Vec<_>>().join(" "))}}}}
